param([string]$JarvisRoot="C:\Abutron\Jarvis")
$ErrorActionPreference='Stop'; $line=Get-Content (Join-Path $JarvisRoot '.env')|?{$_ -match '^JARVIS_API_TOKEN='}|Select-Object -First 1; $tok=$line.Substring(17).Trim(); $H=@{Authorization="Bearer $tok"}; Invoke-RestMethod 'http://127.0.0.1:8788/health'|Format-List
try{Invoke-RestMethod 'http://127.0.0.1:8788/incidents' -ErrorAction Stop|Out-Null; throw 'AUTH FAIL'}catch{if($_.Exception.Response.StatusCode.value__ -ne 401){throw}}; Write-Host 'PASS unauthenticated=401'; Invoke-RestMethod 'http://127.0.0.1:8788/collect' -Method Post -Headers $H|ConvertTo-Json -Depth 8; Invoke-RestMethod 'http://127.0.0.1:8788/incidents' -Headers $H|ConvertTo-Json -Depth 8; Invoke-RestMethod 'http://127.0.0.1:8788/approvals' -Headers $H|ConvertTo-Json -Depth 8; (Invoke-WebRequest 'http://127.0.0.1:8788/metrics' -UseBasicParsing).Content; Get-ScheduledTask 'Abutron-Jarvis-RC1-08'|Select TaskName,State
